mapper.select:
SELECT COUNT(*)
FROM ticket_source_project_mapping
WHERE project_id = #{projectId}

SELECT COUNT(*)
FROM ticket_source_session_mapping
WHERE session_id = #{sessionId}

SELECT COUNT(*)
FROM ticket_source_sku_mapping
WHERE sku_id = #{skuId}

mapper.update:
UPDATE performance_project
SET hot_score = #{hotScore},
    publish_time = #{publishTime},
    update_time = NOW()
WHERE project_id = #{projectId}
  AND EXISTS (
      SELECT 1
      FROM ticket_source_project_mapping tpm
      WHERE tpm.project_id = #{projectId}
  )

mapper.select:
SELECT COUNT(*)
FROM performance_session
WHERE project_id = #{projectId}
  AND venue_id = #{venueId}
  AND start_time = #{startTime}

  AND session_id <> #{excludeSessionId}

mapper.update:
UPDATE performance_session
SET session_status = #{sessionStatus}, update_time = NOW()
WHERE session_id = #{sessionId}

mapper.select:
SELECT COUNT(*)
FROM ticket_sku
WHERE session_id = #{sessionId}
  AND sku_name = #{skuName}

  AND sku_id <> #{excludeSkuId}

mapper.update:
UPDATE ticket_sku
SET sku_status = #{skuStatus}, update_time = NOW(), version = version + 1
WHERE sku_id = #{skuId}

UPDATE ticket_sku
SET price=#{price}, price_mode=#{priceMode}, version=version+1, update_time=NOW()
WHERE sku_id=#{skuId}

UPDATE performance_session
SET min_price = (
        SELECT MIN(price)
        FROM ticket_sku
        WHERE session_id = #{sessionId}
          AND sku_status <> 'OFFLINE'
    ),
    max_price = (
        SELECT MAX(price)
        FROM ticket_sku
        WHERE session_id = #{sessionId}
          AND sku_status <> 'OFFLINE'
    ),
    update_time = NOW()
WHERE session_id = #{sessionId}
